import './NotificationList.css';

export interface Notification {
  id: string;
  message: string;
}

interface NotificationListProps {
  items: Notification[];
  isLoading: boolean;
}

export function NotificationList({ items, isLoading }: NotificationListProps): JSX.Element {
  if (isLoading) {
    return (
      <ul role="list" className="notification-list">
        {[0, 1, 2, 3].map((i) => (
          <li key={i} className="notification-list__item notification-list__item--placeholder">
            <span className="notification-list__bar" />
          </li>
        ))}
      </ul>
    );
  }

  return (
    <ul role="list" className="notification-list">
      {items.map((item) => (
        <li key={item.id} className="notification-list__item">
          {item.message}
        </li>
      ))}
    </ul>
  );
}
